import axios from 'axios';

const API_URL = process.env.VUE_APP_API_URL; // solo existe en desarrollo
const BASE = process.env.BASE_URL || '/';    // '/' en local, '/PROYECTO-7/' en producción

const cliente = axios.create({
  baseURL: API_URL || BASE,
  timeout: 8000
});

// "/img/foto.jpg" -> "/PROYECTO-7/img/foto.jpg"
const conRutaImagen = (p) => ({
  ...p,
  imagen: p.imagen ? BASE + p.imagen.replace(/^\//, '') : p.imagen
});

export const obtenerProductos = () =>
  API_URL
    ? cliente.get('/productos').then((r) => r.data.map(conRutaImagen))
    : cliente.get('db.json').then((r) => r.data.productos.map(conRutaImagen));